package com.opencheps;
import com.opencheps.camera.CameraBackground;
import org.junit.Test;import static org.junit.Assert.*;
public class CameraBackgroundTest {
    private int[] board(){int[] p=new int[320*320];for(int y=0;y<320;y++)for(int x=0;x<320;x++)p[y*320+x]=((x/40+y/40)&1)==0?0xffeeeed2:0xff769656;return p;}
    private void fill(int[] p,int x1,int y1,int x2,int y2,int color){for(int y=y1;y<y2;y++)for(int x=x1;x<x2;x++)p[y*320+x]=color;}
    @Test public void acceptsVisibleBoard(){int[] p=board();assertTrue(new CameraBackground(p,320,320).visible(p,320,320));}
    @Test public void allowsTwoMoveHighlights(){int[] p=board();CameraBackground b=new CameraBackground(p,320,320);fill(p,160,160,200,200,0xffffff60);fill(p,160,240,200,280,0xffffff60);assertTrue(b.visible(p,320,320));}
    @Test public void allowsCheckedKingWithLastMoveHighlights(){int[] p=board();CameraBackground b=new CameraBackground(p,320,320);fill(p,160,160,200,200,0xffffff60);fill(p,160,240,200,280,0xffffff60);fill(p,160,0,200,40,0xffdd3333);assertTrue(b.visible(p,320,320));}
    @Test public void rejectsHandOverEmptyCells(){int[] p=board();CameraBackground b=new CameraBackground(p,320,320);fill(p,80,80,200,200,0xffa98367);assertFalse(b.visible(p,320,320));}
    @Test public void allowsGlobalExposureShift(){int[] p=board();CameraBackground b=new CameraBackground(p,320,320);for(int i=0;i<p.length;i++){int c=p[i];p[i]=0xff000000|(Math.min(255,((c>>16)&255)+8)<<16)|(Math.min(255,((c>>8)&255)+5)<<8)|Math.min(255,(c&255)+10);}assertTrue(b.visible(p,320,320));}
    @Test public void ignoresPieceCenters(){int[] p=board();CameraBackground b=new CameraBackground(p,320,320);for(int r=0;r<8;r++)for(int f=0;f<8;f++)fill(p,f*40+12,r*40+12,f*40+28,r*40+28,0xff111111);assertTrue(b.visible(p,320,320));}
    @Test public void recoversWhenHandIsRemoved(){int[] clear=board(),covered=clear.clone();CameraBackground b=new CameraBackground(clear,320,320);fill(covered,80,80,200,200,0xffa98367);assertFalse(b.visible(covered,320,320));assertTrue(b.visible(clear,320,320));}
    @Test public void joiningOnHighlightedMoveDoesNotBlockNextMove(){int[] old=board();fill(old,160,40,200,80,0xffffff60);fill(old,160,120,200,160,0xffffff60);CameraBackground b=new CameraBackground(old,320,320);int[] next=board();fill(next,80,240,120,280,0xffffff60);fill(next,80,160,120,200,0xffffff60);assertTrue(b.visible(next,320,320));}
    @Test public void previousCheckAndHighlightsMayDisappearTogether(){int[] old=board();fill(old,160,40,200,80,0xffffff60);fill(old,160,120,200,160,0xffffff60);fill(old,160,0,200,40,0xffdd3333);CameraBackground b=new CameraBackground(old,320,320);int[] next=board();fill(next,80,240,120,280,0xffffff60);fill(next,80,160,120,200,0xffffff60);fill(next,160,280,200,320,0xffdd3333);assertTrue(b.visible(next,320,320));}
    @Test public void staleHighlightsDoNotConsumeHandBudget(){int[] old=board();fill(old,160,40,200,80,0xffffff60);fill(old,160,120,200,160,0xffffff60);CameraBackground b=new CameraBackground(old,320,320);int[] next=board();fill(next,80,80,160,160,0xffa98367);assertFalse(b.visible(next,320,320));}
    @Test public void referenceRemainsFixedAfterCoveredFrame(){int[] old=board();fill(old,160,40,200,80,0xffffff60);fill(old,160,120,200,160,0xffffff60);CameraBackground b=new CameraBackground(old,320,320);int[] hand=board();fill(hand,80,80,200,200,0xffa98367);assertFalse(b.visible(hand,320,320));assertTrue(b.visible(board(),320,320));}
    @Test public void capturedLightingOutliersMustVerifyTheirOwnFrame(){int[] p=board();for(int cell:new int[]{0,2,16,18})fill(p,cell%8*40,cell/8*40,(cell%8+1)*40,(cell/8+1)*40,0xff88aa33);CameraBackground b=new CameraBackground(p,320,320);assertTrue(b.visible(p,320,320));assertTrue(b.visible(board(),320,320));}
    @Test public void stableLightingOutliersDoNotHideANewHand(){int[] p=board();for(int cell:new int[]{0,2,16,18})fill(p,cell%8*40,cell/8*40,(cell%8+1)*40,(cell/8+1)*40,0xff88aa33);CameraBackground b=new CameraBackground(p,320,320);int[] hand=p.clone();fill(hand,160,160,240,240,0xffa98367);assertFalse(b.visible(hand,320,320));}
}
